<?php if (!$isAdmin): ?><section class="page wrap business"><?php endif ?>
<?php if ($path==='/orders/new'): ?>
<div class="eyebrow">YOUR WORKSPACE</div><h1>New order</h1><p class="lead">Orders are handled manually. Check your link and quantity before submitting.</p>
<?php $list=$db->query('SELECT * FROM services WHERE active=1 AND rate_poisha_per_1000>0 ORDER BY sort_order,id LIMIT 200')->fetchAll(PDO::FETCH_ASSOC); ?>
<?php if (!$list): ?><div class="panel">No services are currently available to order.</div><?php else: ?>
<form class="panel form-grid" method="post"><?=csrf_field()?><input type="hidden" name="request_key" value="<?=e(form_key())?>"><label>Service<select name="service_id" required><?php foreach($list as $s): ?><option value="<?=(int)$s['id']?>"><?=e($s['title'])?> — <?=e(money((int)$s['rate_poisha_per_1000']))?> / 1,000 · <?=(int)$s['min_quantity']?>–<?=(int)$s['max_quantity']?></option><?php endforeach ?></select></label><label>Public target URL<input type="url" name="target_url" maxlength="2048" required></label><label>Quantity<input type="number" name="quantity" min="1" max="1000000" required></label><p>Cost is calculated from the selected service rate, rounded up to the nearest poisha. Your wallet is charged when you submit.</p><button class="btn">Submit order ↗</button></form><?php endif ?>
<?php elseif ($path==='/orders' || $path==='/admin/orders'): ?>
<div class="eyebrow"><?=$isAdmin?'BUSINESS MANAGEMENT':'YOUR WORKSPACE'?></div><h1>Orders</h1><p class="lead">Track orders and their current status.</p><?php if (!$isAdmin): ?><p><a class="btn" href="/orders/new">New order ↗</a></p><?php endif ?>
<?php if ($isAdmin) { $q=$db->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 100'); } else { $q=$db->prepare('SELECT o.* FROM orders o WHERE user_id=? ORDER BY id DESC LIMIT 100'); $q->execute([$uid]); } $items=$q->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="panel"><h2>Recent orders</h2><?php if (!$items): ?><p>No orders yet.</p><?php endif ?><?php foreach($items as $o): ?><div class="item-row"><div><strong>#<?=(int)$o['id']?> · <?=e($o['service_title'])?></strong><p><?=e((string)$o['quantity'])?> · <?=e(money((int)$o['cost_poisha']))?> · <?=e($o['status'])?><?php if ($isAdmin): ?> · <?=e($o['email'])?><?php endif ?><br><a href="<?=e($o['target_url'])?>" rel="noopener noreferrer" target="_blank">View target ↗</a></p></div><?php if ($isAdmin && in_array($o['status'],['pending','in_progress'],true)): ?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$o['id']?>"><label>Status<select name="status"><option value="in_progress">In progress</option><option value="completed">Completed</option><option value="cancelled">Cancel and refund</option></select></label><button class="btn btn-small">Update</button></form><?php endif ?></div><?php endforeach ?></div>
<?php elseif ($path==='/wallet'): ?>
<?php wallet($db,$uid); $q=$db->prepare('SELECT balance_poisha FROM wallets WHERE user_id=?'); $q->execute([$uid]); $balance=(int)$q->fetchColumn(); $q=$db->prepare('SELECT * FROM ledger WHERE user_id=? ORDER BY id DESC LIMIT 100'); $q->execute([$uid]); $entries=$q->fetchAll(PDO::FETCH_ASSOC); $q=$db->prepare('SELECT * FROM deposits WHERE user_id=? ORDER BY id DESC LIMIT 100'); $q->execute([$uid]); $deposits=$q->fetchAll(PDO::FETCH_ASSOC); ?>
<div class="eyebrow">YOUR WORKSPACE</div><h1>Wallet</h1><p class="lead">Available balance: <strong><?=e(money($balance))?></strong></p><div class="admin-columns"><div class="panel"><h2>Manual payment</h2><?php if (empty($settings['payment_instructions'])): ?><p>Manual payments are not configured yet. Contact an administrator before sending funds.</p><?php else: ?><p><?=nl2br(e($settings['payment_instructions']))?></p><p>Funds are credited only after an administrator verifies the payment.</p><form class="form-grid" method="post"><?=csrf_field()?><input type="hidden" name="request_key" value="<?=e(form_key())?>"><label>Amount (BDT)<input name="amount" inputmode="decimal" placeholder="0.00" required></label><label>Method<select name="method"><option>bKash</option><option>Nagad</option><option>Other</option></select></label><label>Payment reference<input name="reference" maxlength="120" required></label><button class="btn">Submit for verification</button></form><?php endif ?></div><div class="panel"><h2>Payment requests</h2><?php if (!$deposits): ?><p>No requests yet.</p><?php endif ?><?php foreach($deposits as $d): ?><p>#<?=(int)$d['id']?> · <?=e(money((int)$d['amount_poisha']))?> · <?=e($d['method'])?> · <?=e($d['status'])?></p><?php endforeach ?><h2>Transactions</h2><?php if (!$entries): ?><p>No transactions yet.</p><?php endif ?><?php foreach($entries as $entry): ?><p><?=e($entry['kind'])?> #<?=(int)$entry['reference_id']?> · <?=e(money((int)$entry['amount_poisha']))?> <small><?=e($entry['created_at'])?></small></p><?php endforeach ?></div></div>
<?php elseif ($path==='/admin/deposits'): ?>
<div class="eyebrow">BUSINESS MANAGEMENT</div><h1>Payment requests</h1><p class="lead">Verify the reference and amount with your payment provider before approving. Approval credits the wallet.</p>
<?php $items=$db->query('SELECT d.*,u.email FROM deposits d JOIN users u ON u.id=d.user_id ORDER BY d.id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC); ?><div class="panel"><?php if (!$items): ?><p>No payment requests.</p><?php endif ?><?php foreach($items as $d): ?><div class="item-row"><div><strong>#<?=(int)$d['id']?> · <?=e(money((int)$d['amount_poisha']))?> · <?=e($d['status'])?></strong><p><?=e($d['email'])?> · <?=e($d['method'])?> · Reference: <?=e($d['reference'])?></p></div><?php if ($d['status']==='pending'): ?><form method="post" onsubmit="return confirm('Have you independently verified this payment?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$d['id']?>"><button class="btn btn-small" name="decision" value="approved">Approve</button> <button class="btn btn-outline btn-small" name="decision" value="rejected">Reject</button></form><?php endif ?></div><?php endforeach ?></div>
<?php elseif ($path==='/support' || $path==='/admin/support'): ?>
<div class="eyebrow"><?=$isAdmin?'COMMUNICATION':'YOUR WORKSPACE'?></div><h1>Support</h1><p class="lead">Keep your questions and replies in one place.</p>
<?php $id=(int)($_GET['id'] ?? 0); $ticket=null; if($id) { $q=$db->prepare('SELECT * FROM tickets WHERE id=?'.($isAdmin?'':' AND user_id=?')); $q->execute($isAdmin?[$id]:[$id,$uid]); $ticket=$q->fetch(PDO::FETCH_ASSOC); } ?>
<?php if ($ticket): ?><?php $q=$db->prepare('SELECT m.*,u.name FROM ticket_messages m JOIN users u ON u.id=m.user_id WHERE ticket_id=? ORDER BY m.id LIMIT 200'); $q->execute([$id]); $messages=$q->fetchAll(PDO::FETCH_ASSOC); ?><div class="panel"><h2>#<?=$id?> · <?=e($ticket['subject'])?></h2><?php foreach($messages as $m): ?><div class="item-row"><div><strong><?=e($m['name'])?></strong> <small><?=e($m['created_at'])?></small><p><?=nl2br(e($m['body']))?></p></div></div><?php endforeach ?><?php if ($ticket['status']==='open'): ?><form class="form-grid" method="post" action="<?=$isAdmin?'/admin/support':'/support/reply'?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Reply<textarea name="body" maxlength="5000" required></textarea></label><button class="btn">Send reply</button></form><?php endif ?><p><a href="<?=$isAdmin?'/admin/support':'/support'?>">← All tickets</a></p></div>
<?php else: ?><?php if($isAdmin) { $q=$db->query('SELECT t.*,u.email FROM tickets t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 100'); } else { $q=$db->prepare('SELECT * FROM tickets WHERE user_id=? ORDER BY id DESC LIMIT 100'); $q->execute([$uid]); } $tickets=$q->fetchAll(PDO::FETCH_ASSOC); ?><div class="admin-columns"><?php if (!$isAdmin): ?><form class="panel form-grid" method="post"><?=csrf_field()?><h2>Open a ticket</h2><label>Subject<input name="subject" maxlength="150" required></label><label>Message<textarea name="body" maxlength="5000" required></textarea></label><button class="btn">Send ticket ↗</button></form><?php endif ?><div class="panel"><h2>Tickets</h2><?php if (!$tickets): ?><p>No tickets yet.</p><?php endif ?><?php foreach($tickets as $t): ?><div class="item-row"><a href="<?=$isAdmin?'/admin/support':'/support'?>?id=<?=(int)$t['id']?>">#<?=(int)$t['id']?> · <?=e($t['subject'])?> →</a><small><?=e($t['status'])?><?php if($isAdmin): ?> · <?=e($t['email'])?><?php endif ?></small></div><?php endforeach ?></div></div><?php endif ?>
<?php endif ?>
<?php if (!$isAdmin): ?></section><?php endif ?>
